\set ON_ERROR_STOP on
begin;
do $$declare t uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';reviewer uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';marker uuid:='00000000-0000-4000-8000-000000000006';bank uuid;rubric uuid;question uuid;other uuid;ids jsonb:='[]';kind text;mime text;policy jsonb;payload jsonb;definition jsonb;did uuid;ver uuid;win uuid;reg uuid;form jsonb;aid uuid;lease jsonb;data jsonb;reply jsonb;answer jsonb;asset uuid;unused uuid;receipt jsonb;ticket jsonb;bundle jsonb;report jsonb;run uuid;task uuid;context jsonb;scan jsonb;mark jsonb;sequence_count integer;
begin
 select id into bank from public.assessment_item_banks where tenant_id=t limit 1;
 select id into rubric from public.assessment_rubrics where tenant_id=t limit 1;
 foreach kind in array array['file_response','audio_response','video_response'] loop
  mime:=case kind when 'file_response' then 'application/pdf' when 'audio_response' then 'audio/ogg' else 'video/webm' end;
  policy:=jsonb_build_object('schema_version','assessment.media-policy.v1','mimes',jsonb_build_array(mime),'max_bytes',1048576,'sources',jsonb_build_array('upload'));
  payload:=jsonb_build_object('schema_version','assessment.item.v1','type',kind,'prompt','Submit your academic answer','locale','en','max_score',9,'tags','[]'::jsonb,'rubric_id',rubric,'media_response',policy);
  begin perform public.assessment_command(owner,t,'answer-invalid-policy-'||kind,'item.create',jsonb_build_object('bank_id',bank,'item',jsonb_set(payload,'{media_response,mimes}','[null]'),'key','{}'::jsonb));raise exception 'Null answer format accepted';exception when check_violation then null;end;
  question:=(public.assessment_command(owner,t,'answer-create-'||kind,'item.create',jsonb_build_object('bank_id',bank,'item',payload,'key','{}'::jsonb))->>'id')::uuid;
  ids:=ids||jsonb_build_array(question);
  perform public.assessment_command(owner,t,'answer-submit-'||kind,'item.submit',jsonb_build_object('id',question));perform public.assessment_command(reviewer,t,'answer-approve-'||kind,'item.approve',jsonb_build_object('id',question));
 end loop;
 question:=(ids->>0)::uuid;other:=(ids->>1)::uuid;
 definition:=jsonb_build_object('schema_version','assessment.definition.v1','title','Academic media answer assessment','locale','en','duration_seconds',600,'shuffle_items',false,'shuffle_options',false,'sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000001','title','Submissions','item_version_ids',ids,'draw_count',3)));
 did:=(public.assessment_command(owner,t,'answer-definition','assessment.create',jsonb_build_object('definition',definition))->>'id')::uuid;
 ver:=(public.assessment_command(owner,t,'answer-publish','assessment.publish',jsonb_build_object('id',did,'revision',1))->>'id')::uuid;
 win:=(public.assessment_command(owner,t,'answer-window','window.create',jsonb_build_object('assessment_version_id',ver,'title','Academic media sitting','opens_at',clock_timestamp()-interval '1 hour','closes_at',clock_timestamp()+interval '1 hour'))->>'id')::uuid;
 reg:=(public.assessment_command(owner,t,'answer-registration','registration.create',jsonb_build_object('window_id',win,'candidate_id',candidate))->>'id')::uuid;
 form:=jsonb_build_object('schema_version','assessment.manifest.v1','assessment_version_id',ver,'duration_seconds',600,'locale','en','title','Academic media','sections',jsonb_build_array(jsonb_build_object('id','20000000-0000-4000-8000-000000000001','items',(select jsonb_agg(jsonb_build_object('item_version_id',v.id,'item',v.payload)) from public.assessment_item_versions v where ids ? v.id::text))));
 aid:=(public.assessment_command(candidate,t,'answer-start','attempt.start',jsonb_build_object('registration_id',reg,'manifest',form,'manifest_hash',repeat('e',64)))->>'id')::uuid;
 lease:=public.assessment_runtime_command(candidate,t,'answer-lease','lease.acquire',jsonb_build_object('attempt_id',aid,'device_id',candidate,'token_hash',repeat('a',64)));
 lease:=jsonb_build_object('device_id',candidate,'token_hash',repeat('a',64),'epoch',lease#>>'{result,epoch}');
 data:=jsonb_build_object('attempt_id',aid,'item_version_id',question,'source','upload','lease',lease,'upload',jsonb_build_object('filename','Candidate Private Identity.pdf','mime','application/pdf','byte_length',3,'parts',jsonb_build_array(jsonb_build_object('sha256',repeat('b',64),'byte_length',3))));
 begin perform public.assessment_answer_command(owner,t,'answer-wrong-owner','upload.begin',data);raise exception 'Staff admitted an answer for a candidate';exception when no_data_found then null;end;
 begin perform public.assessment_answer_command(candidate,t,'answer-wrong-lease','upload.begin',jsonb_set(data,'{lease,token_hash}',to_jsonb(repeat('c',64))));raise exception 'Stale device admitted an answer';exception when insufficient_privilege then null;end;
 begin perform public.assessment_answer_command(candidate,t,'answer-wrong-source','upload.begin',jsonb_set(data,'{source}','"capture"'));raise exception 'Unapproved capture source admitted';exception when invalid_parameter_value then null;end;
 begin perform public.assessment_answer_command(candidate,t,'answer-wrong-format','upload.begin',jsonb_set(data,'{upload,mime}','"video/webm"'));raise exception 'Unapproved format admitted';exception when invalid_parameter_value then null;end;
 begin perform public.assessment_answer_command(candidate,t,'answer-wrong-size','upload.begin',jsonb_set(data,'{upload,byte_length}','1048577'));raise exception 'Oversized answer admitted';exception when invalid_parameter_value then null;end;
 reply:=public.assessment_answer_command(candidate,t,'answer-admit-file','upload.begin',data);asset:=(reply->>'id')::uuid;
 if public.assessment_answer_command(candidate,t,'answer-admit-file','upload.begin',data)<>reply then raise exception 'Admission receipt changed';end if;
 begin perform public.assessment_answer_command(candidate,t,'answer-admit-file','upload.begin',jsonb_set(data,'{upload,parts,0,sha256}',to_jsonb(repeat('c',64))));raise exception 'Pinned byte manifest changed on replay';exception when unique_violation then null;end;
 answer:=jsonb_build_object('schema_version','assessment.media-answer.v1','artifact_id',asset,'content_hash',reply->>'content_hash');
 begin perform public.assessment_artifact_transport(owner,t,'chunk.authorize',jsonb_build_object('artifact_id',asset,'index',0));raise exception 'Bank author opened candidate upload';exception when no_data_found then null;end;
 if exists(select 1 from jsonb_array_elements(public.assessment_artifact_read(owner,t)->'items') where value->>'id'=asset::text) then raise exception 'Candidate answer appeared in prompt library';end if;
 begin update public.assessment_artifacts set purpose='prompt' where id=asset;raise exception 'Answer purpose changed';exception when check_violation then null;end;
 unused:=(public.assessment_answer_command(candidate,t,'answer-unused-file','upload.begin',data)->>'id')::uuid;
 perform public.assessment_answer_command(candidate,t,'answer-unused-cancel','upload.cancel',jsonb_build_object('artifact_id',unused));
 begin perform pg_temp.assessment_command(candidate,t,'answer-cancelled-selection','response.append',jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',question,'response',jsonb_set(answer,'{artifact_id}',to_jsonb(unused)),'payload_hash','bad'));raise exception 'Cancelled academic answer selected';exception when check_violation then null;end;
 begin perform public.assessment_artifact_command(candidate,t,'answer-author-cancel','upload.cancel',jsonb_build_object('artifact_id',asset));raise exception 'Author namespace cancelled academic answer';exception when no_data_found then null;end;
 begin perform pg_temp.assessment_command(candidate,t,'answer-unknown-hash','response.append',jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',question,'response',jsonb_set(answer,'{content_hash}',to_jsonb(repeat('f',64))),'payload_hash','bad'));raise exception 'Foreign content hash saved';exception when check_violation then null;end;
 begin perform pg_temp.assessment_command(candidate,t,'answer-foreign-question','response.append',jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',other,'response',answer,'payload_hash','bad'));raise exception 'Answer rebound to another question';exception when check_violation then null;end;
 begin perform pg_temp.assessment_command(candidate,t,'answer-extra-field','response.append',jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',question,'response',answer||jsonb_build_object('score',9),'payload_hash','bad'));raise exception 'Caller score entered answer';exception when check_violation then null;end;
 perform pg_temp.assessment_command(candidate,t,'answer-select-file','response.append',jsonb_build_object('attempt_id',aid,'sequence',1,'item_version_id',question,'response',answer,'payload_hash','pinned'));
 begin perform public.assessment_answer_command(candidate,t,'answer-selected-cancel','upload.cancel',jsonb_build_object('artifact_id',asset));raise exception 'Selected academic answer cancelled';exception when check_violation then null;end;
 perform pg_temp.assessment_command(candidate,t,'answer-submit-attempt','attempt.submit',jsonb_build_object('attempt_id',aid));
 begin perform public.assessment_answer_command(candidate,t,'answer-after-deadline','upload.begin',data);raise exception 'New answer admitted after finalization';exception when check_violation then null;end;
 if public.assessment_answer_command(candidate,t,'answer-admit-file','upload.begin',data)<>reply then raise exception 'Lost admission receipt could not recover after finalization';end if;
 -- Complete transport only, after academic finalization; selection stays pinned.
 receipt:=public.assessment_artifact_transport(candidate,t,'chunk.authorize',jsonb_build_object('artifact_id',asset,'index',0));
 begin perform public.assessment_artifact_transport(candidate,t,'chunk.receipt',jsonb_build_object('artifact_id',asset,'index',0,'sha256',repeat('c',64),'byte_length',3));raise exception 'Different bytes accepted after finalization';exception when unique_violation then null;end;
 receipt:=public.assessment_artifact_transport(candidate,t,'chunk.receipt',jsonb_build_object('artifact_id',asset,'index',0,'sha256',repeat('b',64),'byte_length',3,'cipher_sha256',repeat('c',64),'iv',repeat('d',24),'key_id','local-test','object_key','assessment/'||t||'/'||asset||'/0/'||repeat('b',64),'etag','local-test'));
 perform public.assessment_artifact_transport(candidate,t,'upload.complete',jsonb_build_object('artifact_id',asset));
 begin perform public.assessment_artifact_transport(candidate,t,'read.authorize',jsonb_build_object('artifact_id',asset,'attempt_id',aid));raise exception 'Unscanned bytes delivered';exception when check_violation then null;end;
 select value into ticket from jsonb_array_elements(public.assessment_grading_claim(100)) where value->>'attempt_id'=aid::text;
 bundle:=public.assessment_grading_bundle(t,aid,1,(ticket->>'lease_token')::uuid);
 select jsonb_build_object('scorer_version','assessment.scorer.v1','input_hash',bundle->>'input_hash','scores',jsonb_agg(jsonb_build_object('item_version_id',e->>'item_version_id','score',null,'max_score',9,'status','needs_human'))) into report from jsonb_array_elements(bundle->'items') e;
 run:=(public.assessment_grading_commit(t,aid,1,(ticket->>'lease_token')::uuid,report)->>'id')::uuid;
 select id into task from public.assessment_grading_tasks where run_id=run and item_version_id=question;
 perform public.assessment_grading_command(owner,t,'answer-marker-assign','marker.assign',jsonb_build_object('task_id',task,'marker_id',marker,'slot',1));
 context:=public.assessment_grading_read(marker,t,'task',task);
 if context#>>'{answer_asset,state}'<>'quarantined' or (context->>'can_mark')::boolean or context::text like '%Candidate Private Identity%' or context ? 'candidate_id' or context#>'{answer_asset,created_by}' is not null then raise exception 'Blind marker readiness or privacy violated';end if;
 mark:=jsonb_build_object('task_id',task,'criteria',(select jsonb_object_agg(e->>'id',0) from jsonb_array_elements((select criteria from public.assessment_rubrics where id=rubric)) e),'rationale','Reviewed submitted academic file');
 begin perform public.assessment_grading_command(marker,t,'answer-unscanned-mark','mark.submit',mark);raise exception 'Marker graded unscanned file';exception when check_violation then null;end;
 select value into scan from jsonb_array_elements(public.assessment_artifact_scan_claim(20)) where value->>'artifact_id'=asset::text;
 perform public.assessment_artifact_scan_report(jsonb_build_object('job_id',scan->>'job_id','lease_token',scan->>'lease_token','manifest_hash',scan->>'manifest_hash','verdict','clean','detected_mime','application/pdf','decoder_checked',true,'scanner_id','local-scanner-fixture','scanner_version','fixture','signature_version','fixture','report_hash',repeat('a',64)));
 context:=public.assessment_grading_read(marker,t,'task',task);
 if context#>>'{answer_asset,state}'<>'ready' or not (context->>'can_mark')::boolean or context::text like '%Candidate Private Identity%' then raise exception 'Ready blind answer projection incorrect';end if;
 perform public.assessment_artifact_transport(marker,t,'read.authorize',jsonb_build_object('artifact_id',asset,'task_id',task));
 begin perform public.assessment_artifact_transport(marker,t,'read.authorize',jsonb_build_object('artifact_id',asset,'task_id',task,'attempt_id',aid));raise exception 'Ambiguous academic read scope accepted';exception when invalid_parameter_value then null;end;
 begin perform public.assessment_artifact_transport(owner,t,'read.authorize',jsonb_build_object('artifact_id',asset));raise exception 'Institution bank authority bypassed answer scope';exception when no_data_found then null;end;
 perform public.assessment_grading_command(marker,t,'answer-scanned-mark','mark.submit',mark);
 perform public.assessment_grading_command(owner,t,'answer-marker-revoke','marker.revoke',jsonb_build_object('task_id',task,'assignment_id',(select id from public.assessment_grading_assignments where task_id=task and marker_id=marker and revoked_at is null),'reason','Review assignment withdrawn'));
 begin perform public.assessment_artifact_transport(marker,t,'read.authorize',jsonb_build_object('artifact_id',asset,'task_id',task));raise exception 'Revoked marker read academic file';exception when insufficient_privilege then null;end;
 if (select last_sequence from public.assessment_attempts where id=aid)<>1 or (select count(*) from public.assessment_response_journal where attempt_id=aid)<>1 then raise exception 'Transport changed academic answer sequence';end if;
 if has_function_privilege('authenticated','assessment_answer_command(uuid,uuid,text,text,jsonb)','execute') or has_function_privilege('service_role','assessment_prompt_artifact_transport(uuid,uuid,text,jsonb)','execute') or has_table_privilege('authenticated','assessment_answer_assets','select') then raise exception 'Academic authority bypass exposed';end if;
end;$$;
set constraints all immediate;
commit;
